// Room component: collapsible "expander" card with area header (sensors, alerts, group controls) and tiles.
const GROUPS = [
  { key: 'light', icon: 'mdi:lightbulb', label: 'Alle Lichter', color: '#ffc107' },
  { key: 'switch', icon: 'mdi:power-plug', label: 'Alle Geräte & Steckdosen', color: '#2196f3' },
  { key: 'cover', icon: 'mdi:window-shutter', label: 'Alle Jalousien', color: '#9c27b0' },
];
function average(hass, ids) {
  const values = ids.map((id) => numeric(hass.states[id])).filter((v) => v !== null);
  if (!values.length) return null;
  const unit = ids.map((id) => hass.states[id]?.attributes?.unit_of_measurement).find(Boolean) || '';
  const avg = values.reduce((a, b) => a + b, 0) / values.length;
  return `${avg.toFixed(1).replace(/\.0$/, '')}${unit ? ` ${unit}` : ''}`.replace(' %', '%').replace(' °', '°');
}

/**
 * Smart 2-per-row layout algorithm respecting slider vs compact tiles,
 * keeping a strictly stable order regardless of active/on/off state.
 * - Top wide tiles (Media Player/TV, covers) take full width.
 * - Compact non-slider tiles are paired cleanly 2-per-row together.
 * - Slider-capable tiles always take full row width (never paired with other tiles).
 * - Group tiles sit at the bottom in full width.
 */
function applySmartTileLayout(tiles, grid = null) {
  if (!tiles || !tiles.length) return;

  const topWide = [];
  const compactTiles = [];
  const sliderTiles = [];
  const bottomWide = [];

  for (const t of tiles) {
    const isGroup = t.spec?.is_group || t.is_group === true || t.constructor?.name === 'GroupTile';
    if (isGroup) {
      bottomWide.push(t);
    } else if (t.isForceOwnRow) {
      sliderTiles.push(t);
    } else if (t.isAlwaysWide) {
      topWide.push(t);
    } else if (t.hasSlider) {
      sliderTiles.push(t);
    } else {
      compactTiles.push(t);
    }
  }

  topWide.forEach((t) => t.setWide(true));
  sliderTiles.forEach((t) => t.setWide(true));
  bottomWide.forEach((t) => t.setWide(true));

  if (compactTiles.length % 2 === 1) {
    for (let i = 0; i < compactTiles.length - 1; i++) {
      compactTiles[i].setWide(false);
    }
    compactTiles[compactTiles.length - 1].setWide(true);
  } else {
    compactTiles.forEach((t) => t.setWide(false));
  }

  if (grid) {
    const ordered = [...topWide, ...compactTiles, ...sliderTiles, ...bottomWide];
    const current = Array.from(grid.children);
    const changed = current.length !== ordered.length || ordered.some((t, i) => current[i] !== t.el);
    if (changed) {
      grid.replaceChildren(...ordered.map((t) => t.el));
    }
  }
}

/**
 * Smart Grouped Cover Tile for rooms with > 1 shutter.
 * Simultaneously operates all shutters in the room and opens the room subview on click.
 */
class GroupedCoverTile {
  constructor(roomSpec, coverSpecs, ctx) {
    this.roomSpec = roomSpec;
    this.coverSpecs = coverSpecs;
    this.ctx = ctx;
    this.hass = null;
    this.entityIds = coverSpecs.map((c) => c.entity_id);
    this.isWide = true;
    this.isAlwaysWide = true;
    this.hasSlider = false;
    this._build();
  }

  setWide(wide) {
    this.el.classList.toggle('wide', !!wide);
  }

  _build() {
    this.iconEl = icon('mdi:window-shutter');
    this.iconBtn = h('button', {
      class: 'tile-icon',
      style: { color: '#9c27b0', background: 'rgba(156, 39, 176, 0.18)' },
      onClick: (e) => {
        e.stopPropagation();
        if (this.ctx?.isEditMode?.()) {
          const firstCover = this.coverSpecs[0];
          const devId = firstCover?.device_id || parseChannelKey(firstCover?.key).deviceId || null;
          if (devId) { this.ctx.onOpenDevice?.(devId); return; }
        }
        this.ctx.onOpenRoom?.(this.roomSpec.area_id);
      },
    }, this.iconEl);

    this.nameEl = h('div', { class: 'tile-name' }, 'Rollläden');
    this.stateEl = h('div', { class: 'tile-state' }, `${this.coverSpecs.length} Rollläden`);
    this.info = h('div', {
      class: 'tile-info',
      onClick: () => {
        if (this.ctx?.isEditMode?.()) {
          const firstCover = this.coverSpecs[0];
          const devId = firstCover?.device_id || parseChannelKey(firstCover?.key).deviceId || null;
          if (devId) { this.ctx.onOpenDevice?.(devId); return; }
        }
        this.ctx.onOpenRoom?.(this.roomSpec.area_id);
      },
    }, this.nameEl, this.stateEl);

    const mk = (ic, label, fn) => h('button', {
      class: 'mini-btn', 'aria-label': label,
      onClick: (e) => { e.stopPropagation(); fn(); },
    }, icon(ic));

    this.btnUp = mk('mdi:arrow-up', 'Alle öffnen', () => this._service('open'));
    this.btnStop = mk('mdi:stop', 'Alle stoppen', () => this._service('stop'));
    this.btnDown = mk('mdi:arrow-down', 'Alle schließen', () => this._service('close'));

    this.btnDetail = h('button', {
      class: 'mini-btn', 'aria-label': 'Details', title: 'Details',
      onClick: (e) => { e.stopPropagation(); this.ctx.onOpenRoom?.(this.roomSpec.area_id); },
    }, icon('mdi:arrow-right'));

    this.btns = h('div', { class: 'tile-btns' }, this.btnUp, this.btnStop, this.btnDown, this.btnDetail);

    this.el = h('div', {
      class: 'tile grouped-cover wide',
      'data-active': 'true',
    }, h('div', { class: 'tile-main' }, this.iconBtn, this.info, this.btns), editBorder(10));

    this.el.addEventListener('click', (e) => {
      if (this.ctx?.isEditMode?.()) {
        e.stopPropagation();
        e.preventDefault();
        const firstCover = this.coverSpecs[0];
        const devId = firstCover?.device_id || parseChannelKey(firstCover?.key).deviceId || firstCover?.entity_id;
        if (devId) this.ctx.onOpenDevice?.(devId);
      }
    }, true);
  }

  _service(cmd) {
    if (!this.hass) return;
    const byDomain = {};
    for (const id of this.entityIds) {
      const d = domainOf(id);
      (byDomain[d] ||= []).push(id);
    }
    for (const [dom, ids] of Object.entries(byDomain)) {
      if (dom === 'cover') {
        this.hass.callService('cover', cmd === 'stop' ? 'stop_cover' : `${cmd}_cover`, { entity_id: ids });
      } else {
        const svc = cmd === 'stop' ? 'turn_off' : cmd === 'open' ? 'turn_on' : 'turn_off';
        this.hass.callService(dom, svc, { entity_id: ids });
      }
    }
  }

  update(hass) {
    this.hass = hass;
    const states = this.entityIds.map((id) => hass.states[id]).filter(Boolean);
    const openCount = states.filter((s) => s.state !== 'closed' && s.state !== 'unavailable').length;
    const closedCount = states.filter((s) => s.state === 'closed').length;
    const moving = states.some((s) => s.state === 'opening' || s.state === 'closing');

    if (moving) {
      this.stateEl.textContent = 'In Bewegung...';
      this.btnStop.style.color = '#9c27b0';
      this.btnStop.style.background = 'rgba(156, 39, 176, 0.25)';
    } else {
      this.btnStop.style.color = '';
      this.btnStop.style.background = '';
      if (openCount === states.length && states.length > 0) {
        this.stateEl.textContent = 'Alle geöffnet';
      } else if (closedCount === states.length && states.length > 0) {
        this.stateEl.textContent = 'Alle geschlossen';
      } else {
        this.stateEl.textContent = `${closedCount} geschlossen · ${openCount} geöffnet`;
      }
    }
  }
}
class Room {
  /**
   * @param {object} spec  room from backend layout
   * @param {object} ctx   {presets, openState: Map<string, boolean>, onOpenRoom: (areaId) => void}
   */
  constructor(spec, ctx) {
    this.spec = spec;
    this.ctx = ctx;
    this.hass = null;

    const makeTileInstance = (t) => {
      if (t.is_group) return new GroupTile(t, ctx);
      return new Tile(t, ctx);
    };

    // Smart Rollladen Gruppierung:
    // If room has > 1 cover, group them into a single master GroupedCoverTile
    const covers = spec.tiles.filter((t) => effectiveCategory(t) === 'cover');
    if (covers.length > 1) {
      this.groupedCover = new GroupedCoverTile(spec, covers, ctx);
      const nonCovers = spec.tiles.filter((t) => effectiveCategory(t) !== 'cover');
      this.tiles = [this.groupedCover, ...nonCovers.map(makeTileInstance)];
    } else {
      this.tiles = spec.tiles.map(makeTileInstance);
    }

    // Strict priority in room: 1. Jalousien (Rollläden), 2. Medien / TV, 3. Der Rest
    const tileWeight = (t) => {
      if (t instanceof GroupedCoverTile) return 0;
      const cat = effectiveCategory(t);
      if (cat === 'cover') return 0;
      if (cat === 'media_player') return 1;
      if (cat === 'light') return 2;
      if (cat === 'outlet') return 3;
      if (cat === 'switch') return 4;
      return 5;
    };
    this.tiles.sort((a, b) => tileWeight(a) - tileWeight(b));

    this._build();
  }

  get open() {
    if (this.spec.always_open) return true;
    const saved = this.ctx.openState.get(this.spec.area_id);
    return saved === undefined ? !!this.spec.expanded : saved;
  }

  _build() {
    const { spec } = this;

    // Group controls (all lights / switches / covers of this room based on effective category)
    this.groups = GROUPS
      .map((g) => {
        let matchingTiles = [];
        if (g.key === 'light') {
          matchingTiles = spec.tiles.filter((t) => effectiveCategory(t) === 'light');
        } else if (g.key === 'switch') {
          matchingTiles = spec.tiles.filter((t) => ['switch', 'outlet', 'valve', 'pumpe'].includes(effectiveCategory(t)));
        } else if (g.key === 'cover') {
          matchingTiles = spec.tiles.filter((t) => effectiveCategory(t) === 'cover');
        }
        const collectIds = (list) => {
          const out = [];
          const seen = new Set();
          for (const t of list) {
            const eids = t.is_group && Array.isArray(t.entity_ids)
              ? t.entity_ids
              : (t.entity_id ? [t.entity_id] : []);
            for (const eid of eids) {
              if (eid && !seen.has(eid)) {
                seen.add(eid);
                out.push(eid);
              }
            }
          }
          return out;
        };
        return {
          ...g,
          ids: collectIds(matchingTiles),
        };
      })
      .filter((g) => g.ids.length > 0)
      .map((g) => {
        const btn = h('button', {
          class: 'ctrl-btn', 'aria-label': g.label,
          style: { '--group-color': g.color },
          onClick: (e) => { e.stopPropagation(); this._toggleGroup(g); },
        }, icon(g.icon));
        return { ...g, btn };
      });

    // Room detail view button (sub-menu navigation)
    this.detailBtn = h('button', {
      class: 'ctrl-btn', 'aria-label': `${spec.name} Details`, title: 'Details',
      onClick: (e) => { e.stopPropagation(); this.ctx.onOpenRoom?.(this.spec.area_id); },
    }, icon('mdi:arrow-right'));

    this.metaEl = h('div', { class: 'room-meta', hidden: true });
    this.controlsEl = h('div', { class: 'room-controls' }, ...this.groups.map((g) => g.btn), this.detailBtn);

    this.head = h('div', {
      class: 'room-head', role: 'button', tabindex: '0', 'aria-expanded': String(this.open),
      onClick: () => {
        if (this.ctx?.isEditMode?.()) {
          this.ctx.onEditRoom?.(this.spec);
          return;
        }
        this._toggleOpen();
      },
      onKeydown: (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          if (this.ctx?.isEditMode?.()) this.ctx.onEditRoom?.(this.spec);
          else this._toggleOpen();
        }
      },
    },
      h('div', { class: 'room-icon' }, icon(spec.icon)),
      h('div', { class: 'room-title' }, h('div', { class: 'room-name' }, spec.name), this.metaEl),
      this.controlsEl,
      icon('mdi:chevron-down', 'chevron'),
      editBorder(17));

    // Capture clicks anywhere on the room header in Edit Mode (except chevron expand/collapse)
    this.head.addEventListener('click', (e) => {
      if (this.ctx?.isEditMode?.()) {
        e.stopPropagation();
        e.preventDefault();
        if (e.target.closest('.chevron')) {
          this._toggleOpen();
          return;
        }
        this.ctx.onEditRoom?.(this.spec);
      }
    }, true);

    this.grid = h('div', { class: 'tile-grid' }, this.tiles.map((t) => t.el));
    this.el = h('div', { class: 'card room' },
      this.head,
      h('div', { class: 'room-body' }, h('div', { class: 'room-body-inner' }, this.grid)));
    this._applyOpen();
    applySmartTileLayout(this.tiles, this.grid);
  }

  _applyOpen() {
    this.el.toggleAttribute('data-open', this.open);
    this.el.toggleAttribute('data-always', !!this.spec.always_open);
    this.head.setAttribute('aria-expanded', String(this.open));
  }

  _toggleOpen() {
    if (this.spec.always_open) return;
    this.ctx.openState.set(this.spec.area_id, !this.open);
    this._applyOpen();
  }

  _toggleGroup(group) {
    const states = group.ids.map((id) => this.hass.states[id]).filter(Boolean);
    if (group.key === 'cover') {
      const anyOpen = states.some((s) => s.state !== 'closed');
      const targetService = anyOpen ? 'close_cover' : 'open_cover';
      for (const id of group.ids) {
        const dom = domainOf(id);
        if (dom === 'cover') {
          this.hass.callService('cover', targetService, { entity_id: id });
        } else {
          this.hass.callService(dom, targetService === 'close_cover' ? 'turn_off' : 'turn_on', { entity_id: id });
        }
      }
    } else {
      const anyOn = states.some((s) => isActive(s));
      const targetService = anyOn ? 'turn_off' : 'turn_on';
      const valveIds = [];
      const genericIds = [];
      for (const id of group.ids) {
        if (domainOf(id) === 'valve') {
          valveIds.push(id);
        } else {
          genericIds.push(id);
        }
      }
      if (genericIds.length) {
        this.hass.callService('homeassistant', targetService, { entity_id: genericIds });
      }
      if (valveIds.length) {
        this.hass.callService('valve', targetService === 'turn_on' ? 'open_valve' : 'close_valve', { entity_id: valveIds });
      }
    }
  }

  update(hass) {
    this.hass = hass;
    this.tiles.forEach((t) => t.update(hass));
    applySmartTileLayout(this.tiles, this.grid);

    // Group controls
    for (const g of this.groups) {
      const states = g.ids.map((id) => hass.states[id]).filter(Boolean);
      const count = g.key === 'cover'
        ? states.filter((s) => s.state !== 'closed').length
        : states.filter((s) => isActive(s)).length;
      g.btn.toggleAttribute('data-on', count > 0);
    }

    // Header meta: temperature, humidity, alerts
    const { sensors } = this.spec;
    const chips = [];
    const temp = sensors.temperature?.length ? average(hass, sensors.temperature) : null;
    const hum = sensors.humidity?.length ? average(hass, sensors.humidity) : null;
    if (temp) chips.push(h('span', {}, icon('mdi:thermometer'), temp));
    if (hum) chips.push(h('span', {}, icon('mdi:water-percent'), hum));
    const isSensorOn = (id) => {
      const st = hass.states[id];
      if (!st) return false;
      const v = String(st.state || '').toLowerCase();
      return isActive(st) || ['on', 'home', 'detected', 'occupied', 'true'].includes(v);
    };
    if ((sensors.motion || []).some(isSensorOn)) {
      chips.push(h('span', { class: 'alert' }, icon('mdi:motion-sensor'), 'Bewegung'));
    }
    if ((sensors.moisture || []).some(isSensorOn)) {
      chips.push(h('span', { class: 'alert' }, icon('mdi:water-alert'), 'Feuchtigkeit'));
    }
    const key = chips.map((c) => c.textContent).join('|');
    if (key !== this._metaKey) {
      this._metaKey = key;
      this.metaEl.replaceChildren(...chips);
      this.metaEl.hidden = chips.length === 0;
    }
  }
}
// ─── END: components/room.js ───


// ─── START: components/room_detail.js ───
// Room detail subview: dedicated granular control page for a single room.
class RoomDetailView {
  constructor(roomSpec, ctx, onBack) {
    this.spec = roomSpec;
    this.ctx = { ...(ctx || {}), isDetail: true };
    this.onBack = onBack;
    this.hass = null;

    const tiles = roomSpec.tiles || [];
    // Partition by effective category (custom category takes priority!)
    this.coverSpecs = tiles.filter((t) => effectiveCategory(t) === 'cover');
    this.lightSpecs = tiles.filter((t) => effectiveCategory(t) === 'light');
    this.switchSpecs = tiles.filter((t) => ['switch', 'outlet', 'valve', 'pumpe'].includes(effectiveCategory(t)));
    this.mediaSpecs = tiles.filter((t) => effectiveCategory(t) === 'media_player');
    this.otherSpecs = tiles.filter((t) =>
      !['cover', 'light', 'switch', 'outlet', 'valve', 'pumpe', 'media_player'].includes(effectiveCategory(t)));

    const makeTileInstance = (t) => {
      if (t.is_group) return new GroupTile(t, this.ctx);
      return new Tile(t, this.ctx);
    };

    // Strict priority for non-cover devices: 1. Media, 2. Light, 3. Switches, 4. Other
    const otherDeviceSpecs = [
      ...this.mediaSpecs,
      ...this.lightSpecs,
      ...this.switchSpecs,
      ...this.otherSpecs,
    ];
    this.childTiles = otherDeviceSpecs.map(makeTileInstance);

    this._build();
  }

  _build() {
    const { spec } = this;

    // ── Header Left ──
    const titleWrap = h('div', { class: 'room-detail-title-wrap' },
      h('div', { class: 'icon' }, icon(spec.icon || 'mdi:home')),
      h('h2', { class: 'room-detail-title' }, spec.name));

    this.metaEl = h('div', { class: 'room-detail-meta' });

    // ── Header Right: Group Quick Action Controls (Identical to Room cards: Icon + active count badge) ──
    this.groups = GROUPS
      .map((g) => {
        let matchingTiles = [];
        if (g.key === 'light') matchingTiles = this.lightSpecs;
        else if (g.key === 'cover') matchingTiles = this.coverSpecs;
        else if (g.key === 'switch') matchingTiles = this.switchSpecs;
        const ids = [];
        const seen = new Set();
        for (const t of matchingTiles) {
          const eids = t.is_group && Array.isArray(t.entity_ids)
            ? t.entity_ids
            : (t.entity_id ? [t.entity_id] : []);
          for (const eid of eids) {
            if (eid && !seen.has(eid)) {
              seen.add(eid);
              ids.push(eid);
            }
          }
        }
        return {
          ...g,
          ids,
        };
      })
      .filter((g) => g.ids.length > 0)
      .map((g) => {
        const countEl = h('span', { class: 'count', hidden: true });
        const btn = h('button', {
          class: 'ctrl-btn', 'aria-label': g.label,
          style: { '--group-color': g.color },
          onClick: (e) => { e.stopPropagation(); this._toggleGroup(g); },
        }, icon(g.icon), countEl);
        return { ...g, btn, countEl };
      });

    this.actionsEl = h('div', { class: 'room-detail-actions' }, ...this.groups.map((g) => g.btn));

    const head = h('div', { class: 'room-detail-head' },
      h('div', { class: 'room-detail-left' }, titleWrap, this.metaEl),
      this.actionsEl);

    // ── Body: Unified Device Container ──
    const bodyChildren = [];

    // 1. Cover rows (granular position sliders & controls)
    if (this.coverSpecs.length > 0) {
      this.coverRows = this.coverSpecs.map((cSpec) => this._buildCoverRow(cSpec));
      const coverList = h('div', { class: 'cover-detail-list' }, ...this.coverRows.map((cr) => cr.row));
      bodyChildren.push(coverList);
    }

    // 2. All other tiles in responsive smart grid (Media, Lights, Switches, Others)
    if (this.childTiles.length > 0) {
      this.gridEl = h('div', { class: 'tile-grid' }, this.childTiles.map((t) => t.el));
      bodyChildren.push(this.gridEl);
      this._orderAndLayoutTiles();
    }

    const bodyCard = h('div', { class: 'card room-detail-body' }, ...bodyChildren);

    this.el = h('div', { class: 'room-detail-page' }, head, bodyCard);
  }

  _coverService(spec, action, data = {}) {
    const rawDom = domainOf(spec.entity_id);
    if (rawDom !== 'cover') {
      if (action === 'open_cover') return this.hass?.callService(rawDom, 'turn_on', { entity_id: spec.entity_id });
      if (action === 'close_cover') return this.hass?.callService(rawDom, 'turn_off', { entity_id: spec.entity_id });
      if (action === 'stop_cover') return this.hass?.callService(rawDom, 'turn_off', { entity_id: spec.entity_id });
    }
    return this.hass?.callService('cover', action, { entity_id: spec.entity_id, ...data });
  }

  _toggleGroup(group) {
    if (!this.hass) return;
    const states = group.ids.map((id) => this.hass.states[id]).filter(Boolean);
    if (group.key === 'cover') {
      const anyOpen = states.some((s) => s.state !== 'closed');
      const targetService = anyOpen ? 'close_cover' : 'open_cover';
      for (const id of group.ids) {
        const dom = domainOf(id);
        if (dom === 'cover') {
          this.hass.callService('cover', targetService, { entity_id: id });
        } else {
          this.hass.callService(dom, targetService === 'close_cover' ? 'turn_off' : 'turn_on', { entity_id: id });
        }
      }
    } else {
      const anyOn = states.some((s) => isActive(s));
      const targetService = anyOn ? 'turn_off' : 'turn_on';
      const byDomain = {};
      for (const id of group.ids) {
        const dom = domainOf(id);
        (byDomain[dom] ||= []).push(id);
      }
      for (const [dom, ids] of Object.entries(byDomain)) {
        if (['light', 'switch', 'input_boolean'].includes(dom)) {
          this.hass.callService(dom, targetService, { entity_id: ids });
        } else if (dom === 'valve') {
          this.hass.callService('valve', targetService === 'turn_on' ? 'open_valve' : 'close_valve', { entity_id: ids });
        } else {
          this.hass.callService('homeassistant', targetService, { entity_id: ids });
        }
      }
    }
  }

  _buildCoverRow(spec) {
    const iconEl = icon('mdi:window-shutter');
    const nameEl = h('div', { class: 'cover-detail-name' }, spec.name);
    const stateEl = h('div', { class: 'cover-detail-state' }, 'Laden...');

    const mkBtn = (ic, lbl, fn) => h('button', {
      class: 'mini-btn', 'aria-label': lbl,
      onClick: (e) => { e.stopPropagation(); fn(); },
    }, icon(ic));

    const btnUp = mkBtn('mdi:arrow-up', 'Öffnen', () => this._coverService(spec, 'open_cover'));
    const btnStop = mkBtn('mdi:stop', 'Stopp', () => this._coverService(spec, 'stop_cover'));
    const btnDown = mkBtn('mdi:arrow-down', 'Schließen', () => this._coverService(spec, 'close_cover'));

    const slider = h('input', {
      type: 'range', class: 'slider', min: '0', max: '100', step: '1', 'aria-label': `${spec.name} Position`,
      style: { touchAction: 'none', '--tile-color': '#9c27b0' },
    });
    slider.addEventListener('pointerdown', (e) => e.stopPropagation());
    slider.addEventListener('touchstart', (e) => e.stopPropagation(), { passive: true });
    slider.addEventListener('touchmove', (e) => e.stopPropagation(), { passive: true });
    slider.addEventListener('click', (e) => e.stopPropagation());

    let dragging = false;
    slider.addEventListener('input', () => {
      dragging = true;
      setSliderVal(slider, slider.value);
      stateEl.textContent = `Position: ${slider.value}%`;
    });
    slider.addEventListener('change', () => {
      dragging = false;
      const rawDom = domainOf(spec.entity_id);
      if (rawDom === 'cover') {
        this.hass?.callService('cover', 'set_cover_position', {
          entity_id: spec.entity_id,
          position: Number(slider.value),
        });
      } else {
        this.hass?.callService(rawDom, Number(slider.value) > 0 ? 'turn_on' : 'turn_off', {
          entity_id: spec.entity_id,
        });
      }
    });

    const sliderWrap = h('div', { class: 'cover-slider-wrap' },
      h('span', { class: 'cover-slider-label' }, '0%'),
      slider,
      h('span', { class: 'cover-slider-label' }, '100%'));

    const row = h('div', { class: 'cover-detail-row' },
      h('div', { class: 'cover-detail-top' },
        h('div', {
          class: 'cover-detail-info',
          onClick: () => {
            if (this.ctx?.isEditMode?.()) {
              const devId = spec.device_id || parseChannelKey(spec.key).deviceId || spec.entity_id;
              if (devId) { this.ctx.onOpenDevice?.(devId); return; }
            }
          },
        },
          h('div', { class: 'cover-detail-icon' }, iconEl),
          h('div', { class: 'cover-detail-texts' }, nameEl, stateEl)),
        h('div', { class: 'tile-btns' }, btnUp, btnStop, btnDown)),
      sliderWrap,
      editBorder(10));

    row.addEventListener('pointerdown', (e) => {
      if (this.ctx?.isEditMode?.()) {
        e.stopPropagation();
        e.preventDefault();
      }
    }, true);
    row.addEventListener('click', (e) => {
      if (this.ctx?.isEditMode?.()) {
        e.stopPropagation();
        e.preventDefault();
        const devId = spec.device_id || parseChannelKey(spec.key).deviceId || spec.entity_id;
        if (devId) this.ctx.onOpenDevice?.(devId);
      }
    }, true);

    return {
      spec, row, iconEl, stateEl, slider, btnUp, btnStop, btnDown,
      get dragging() { return dragging; },
    };
  }

  update(hass) {
    this.hass = hass;

    // Group quick controls
    if (this.groups) {
      for (const g of this.groups) {
        const states = g.ids.map((id) => hass.states[id]).filter(Boolean);
        const count = g.key === 'cover'
          ? states.filter((s) => s.state !== 'closed').length
          : states.filter((s) => isActive(s)).length;
        g.btn.toggleAttribute('data-on', count > 0);
        g.countEl.hidden = count === 0;
        g.countEl.textContent = String(count);
      }
    }

    // Update child tiles
    this.childTiles.forEach((t) => t.update(hass));
    if (this.childTiles.length > 0) {
      this._orderAndLayoutTiles();
    }

    // Update covers with granular positions
    if (this.coverRows) {
      for (const cr of this.coverRows) {
        const st = hass.states[cr.spec.entity_id];
        const unav = isUnavailable(st);
        cr.iconEl.setAttribute('icon', entityIcon(cr.spec.entity_id, st, cr.spec.icon, cr.spec.category));
        cr.btnUp.disabled = unav;
        cr.btnStop.disabled = unav;
        cr.btnDown.disabled = unav;
        cr.slider.disabled = unav;

        if (unav) {
          cr.stateEl.textContent = 'Nicht verfügbar';
          continue;
        }

        const pos = st?.attributes?.current_position != null ? Number(st.attributes.current_position) : null;
        const state = st?.state;
        const moving = state === 'opening' || state === 'closing';

        if (moving) {
          cr.stateEl.textContent = state === 'opening' ? 'Öffnet...' : 'Schließt...';
          cr.btnStop.style.color = '#9c27b0';
        } else {
          cr.btnStop.style.color = '';
          const posTxt = pos != null ? ` · ${pos}%` : '';
          cr.stateEl.textContent = (state === 'closed' ? 'Geschlossen' : 'Geöffnet') + posTxt;
        }

        if (pos != null && !cr.dragging) {
          setSliderVal(cr.slider, pos);
        }
      }
    }

    // Header sensors chips
    const { sensors } = this.spec;
    const chips = [];
    const temp = sensors.temperature?.length ? average(hass, sensors.temperature) : null;
    const hum = sensors.humidity?.length ? average(hass, sensors.humidity) : null;
    if (temp) chips.push(h('div', { class: 'room-detail-chip' }, icon('mdi:thermometer'), temp));
    if (hum) chips.push(h('div', { class: 'room-detail-chip' }, icon('mdi:water-percent'), hum));
    if ((sensors.motion || []).some((id) => hass.states[id]?.state === 'on')) {
      chips.push(h('div', { class: 'room-detail-chip', style: { color: '#ffb74d' } }, icon('mdi:motion-sensor'), 'Bewegung'));
    }
    if ((sensors.moisture || []).some((id) => hass.states[id]?.state === 'on')) {
      chips.push(h('div', { class: 'room-detail-chip', style: { color: '#e57373' } }, icon('mdi:water-alert'), 'Feuchtigkeit'));
    }
    this.metaEl.replaceChildren(...chips);
  }

  _orderAndLayoutTiles() {
    if (!this.gridEl || !this.childTiles.length) return;
    applySmartTileLayout(this.childTiles, this.gridEl);
  }
}
